package Git::MoreHooks::CheckNonASCII;

use strict;
use warnings;

# ABSTRACT: GitHooks plugin to keep non-ASCII characters out of a repository

# VERSION: generated by DZP::OurPkgVersion

use utf8;
use Const::Fast;
use Encode   qw( decode );
use English  qw( -no_match_vars );
use Log::Any qw( $log );
use Git::Hooks 4.0;
use List::Util qw( any );
use Text::Glob qw( glob_to_regex );

my $PKG = __PACKAGE__;
my $CFG = __PACKAGE__ =~ s/.*::/githooks./rmsx;

# How many findings to report for one file before saying how many are left. A
# file that is mostly non-ASCII -- a misdetected binary, a translation table --
# would otherwise bury the output and tell the reader nothing the first ten did
# not.
const my $DEFAULT_MAX_REPORT => 10;

# The last codepoint this plugin has no objection to.
const my $ASCII_MAX => 0x7f;

# Above this, a blob is left unread. Deliberately far above any source file:
# the point is to avoid slurping something enormous, not to have an opinion
# about size. See "max-size" in the documentation for what it costs.
const my $DEFAULT_MAX_SIZE => 5 * 1024 * 1024;

#############
# Grok hook configuration, check it and set defaults.

sub _setup_config {
    my ($git) = @_;

    # A test may run several configurations through one repository object, so a
    # cache that outlived the change would answer for the previous one.
    delete $git->cache('checknonascii')->{'patterns'};

    my $config = $git->get_config();
    $config->{ lc $CFG } //= {};
    my $default = $config->{ lc $CFG };

    # No default patterns. Unset 'name' means every file, because the rule this
    # plugin exists for is repository-wide; 'skip' is how a repository carves
    # out the files where non-ASCII is the point.
    $default->{'name'}       //= [];
    $default->{'skip'}       //= [];
    $default->{'max-report'} //= [$DEFAULT_MAX_REPORT];
    $default->{'max-size'}   //= [$DEFAULT_MAX_SIZE];

    return;
}

#############
# Internals

# Delimiters that come in pairs, so qr{...} and qr<...> work and do not demand
# that the closing delimiter be the opening one typed twice.
my %CLOSER = ( '{' => '}', '(' => ')', '[' => ']', '<' => '>' );

# A configured pattern is either qr<delim>...<delim>, used as written, or a
# glob. Same grammar as CheckPerl's 'name', so a user who knows one knows both.
sub _compile_pattern {
    my ($pattern) = @_;

    if ( $pattern =~ m/\Aqr(.)(.*)(.)\z/msx ) {
        my ( $open, $body, $closer ) = ( $1, $2, $3 );
        my $want = $CLOSER{$open} // $open;

        # Used exactly as the repository wrote it. Imposing /msx here would
        # change the meaning of a pattern somebody else composed.
        ## no critic (RegularExpressions::RequireDotMatchAnything)
        ## no critic (RegularExpressions::RequireExtendedFormatting)
        ## no critic (RegularExpressions::RequireLineBoundaryMatching)
        return qr/$body/ if $closer eq $want;
    }

    # Patterns are matched against the whole path, so a wildcard has to cross
    # directory separators: Text::Glob's default would leave `name = *.pm`
    # matching nothing below the top directory, which is not what anybody
    # writing it means. The package variable IS Text::Glob's documented
    # interface for this, and it is localised.
    local $Text::Glob::strict_wildcard_slash = 0;    ## no critic (Variables::ProhibitPackageVars)
    return glob_to_regex($pattern);
}

sub _patterns {
    my ($git) = @_;

    my $cache = $git->cache('checknonascii');
    return $cache->{'patterns'} if $cache->{'patterns'};

    my $config = $git->get_config($CFG);
    my %patterns;
    foreach my $which (qw( name skip )) {
        $patterns{$which} = [ map { _compile_pattern($_) } @{ $config->{$which} } ];
    }

    $cache->{'patterns'} = \%patterns;
    return $cache->{'patterns'};
}

# Git's own test for a binary file is a NUL byte near the start, and a plugin
# that disagreed with git about which files are text would be the thing at
# fault. Skipping them is not a concession: a PNG is full of bytes above 0x7F
# and none of them is a homoglyph.
sub _is_binary {
    my ($content) = @_;
    return index( $content, "\0" ) >= 0;
}

# What was found, named rather than printed. The character itself is NOT put in
# the message: the whole class of attack this plugin reports is characters that
# do not look like what they are, and a report is read in a terminal, pasted
# into an issue and scrolled past. A codepoint can be looked up; a zero-width
# character in a report is invisible twice over.
#
# Returns the description and how many bytes it accounted for.
sub _describe {
    my ( $bytes, $at ) = @_;

    my $lead = ord substr $bytes, $at, 1;

    # Length is implied by the lead byte. Anything else cannot start a UTF-8
    # sequence, so it is reported as the byte it is. The numbers are the
    # boundaries UTF-8 itself defines, so naming them would say less than they
    # already do.
    ## no critic (ValuesAndExpressions::ProhibitMagicNumbers)
    my $width =
        ( $lead >= 0xc2 && $lead <= 0xdf ) ? 2
      : ( $lead >= 0xe0 && $lead <= 0xef ) ? 3
      : ( $lead >= 0xf0 && $lead <= 0xf4 ) ? 4
      :                                      0;

    if ($width) {
        my $sequence = substr $bytes, $at, $width;
        if ( length $sequence == $width ) {
            my $char = eval { decode( 'UTF-8', $sequence, Encode::FB_CROAK() ) };
            if ( defined $char && length $char == 1 ) {
                return ( sprintf( 'U+%04X', ord $char ), $width );
            }
        }
    }

    # Not valid UTF-8. Worth saying so plainly rather than guessing: it is also
    # how a file in another encoding announces itself.
    return ( sprintf( 'byte 0x%02X (not valid UTF-8)', $lead ), 1 );
}

#############
# Checks

# Every finding in one file. Returns the number reported.
sub file_errors {
    my ( $git, $commit, $filename, $content ) = @_;
    $log->debugf( "$PKG: file_errors(%s, %s)", $commit, $filename );

    my $max = ( $git->get_config( $CFG => 'max-report' ) )[0] // $DEFAULT_MAX_REPORT;
    my @findings;

    # All three line endings, so that a line number means the same thing
    # whatever platform the file was written on. Splitting on \n alone reported
    # every finding in a CR-only file as line 1, and left the CR of a CRLF file
    # at the end of the line.
    my $line_number = 0;
    foreach my $line ( split /\r\n|[\r\n]/msx, $content ) {
        $line_number++;
        next if $line !~ m/[^\x00-\x7f]/msx;

        my $at = 0;
        while ( $at < length $line ) {
            if ( ord( substr $line, $at, 1 ) <= $ASCII_MAX ) {
                $at++;
                next;
            }
            my ( $what, $width ) = _describe( $line, $at );
            push @findings, sprintf '%s:%d byte %d: %s', $filename, $line_number, $at + 1, $what;
            $at += $width;
        }
    }

    return 0 if !@findings;

    my $total = scalar @findings;
    if ( $total > $max ) {
        @findings = @findings[ 0 .. $max - 1 ];
        push @findings, sprintf '... and %d more in this file', $total - $max;
    }

    $git->fault(
        "This file holds characters outside ASCII.\n" . join "\n",
        @findings,
        {
            prefix  => $PKG,
            commit  => $commit,
            option  => 'name',
            details => 'Characters are named by codepoint, not shown, because the '
              . 'point of them is that they do not look like what they are. See '
              . "the plugin documentation for why this is checked.\n",
        },
    );

    return 1;
}

sub check_new_or_modified_files {
    my ( $git, $commit, @files ) = @_;
    $log->debugf( "$PKG: check_new_or_modified_files(%s, %s)", $commit, \@files );

    return 0 if !@files;

    my $patterns = _patterns($git);

    # get_config_integer, not get_config: it parses git's own k, m and g
    # suffixes, so `max-size = 5M` means five mebibytes. Read as a plain string
    # it would have meant five BYTES under numeric comparison, and a plugin that
    # skipped every file over five bytes would have checked nothing at all while
    # looking configured.
    my $max_size = $git->get_config_integer( $CFG => 'max-size' ) // $DEFAULT_MAX_SIZE;
    my $errors   = 0;

    foreach my $filename (@files) {

        ## no critic (RegularExpressions::RequireDotMatchAnything)
        ## no critic (RegularExpressions::RequireExtendedFormatting)
        ## no critic (RegularExpressions::RequireLineBoundaryMatching)
        next if any { $filename =~ m/$_/ } @{ $patterns->{'skip'} };
        next
          if @{ $patterns->{'name'} }
          && !any { $filename =~ m/$_/ } @{ $patterns->{'name'} };

        # The path is checked as well as the content. A file name is shown by
        # every tool that lists a tree, and a bidirectional override in one
        # misrepresents the commit just as well as it does in a source line.
        if ( $filename =~ m/[^\x00-\x7f]/msx ) {
            my ( $what, undef ) = _describe( $filename, $LAST_MATCH_START[0] );
            $git->fault(
                "This file name holds characters outside ASCII: $what",
                { prefix => $PKG, commit => $commit, option => 'name' },
            );
            $errors++;
        }

        # "<commit>:<path>" for a commit and ":0:<path>" for the index are both
        # object names, so one call reads the blob wherever the hook is running.
        # ls-files would have been wrong on the server: a bare repository has no
        # index for the commits being pushed.
        # The object name always begins with the commit-ish, so a path starting
        # with a dash cannot be read as an option and needs no "--" separator --
        # which is just as well, because cat-file does not document one.
        my $blob = "$commit:$filename";

        # Size before content: reading the blob is what costs the memory, so the
        # question has to be asked before the answer is slurped.
        my $size = eval { $git->run( qw( cat-file -s ), $blob ) };
        if ( defined $size && $size > $max_size ) {
            $log->debugf( "$PKG: %s is %s bytes, over max-size %s, skipped", $filename, $size, $max_size );
            next;
        }

        my $content = eval { $git->run( qw( cat-file -p ), $blob ) };
        if ( !defined $content ) {

            # A path that cannot be read is not this plugin's business to
            # report: a symlink, a submodule gitlink, a mode this check has no
            # opinion about.
            $log->debugf( "$PKG: cannot read %s:%s, skipped", $commit, $filename );
            next;
        }

        if ( _is_binary($content) ) {
            $log->debugf( "$PKG: %s is binary, skipped", $filename );
            next;
        }

        $errors += file_errors( $git, $commit, $filename, $content );
    }

    return $errors;
}

sub check_commit {
    my ($git) = @_;
    return check_new_or_modified_files( $git, ':0', $git->filter_files_in_index('AM') );
}

sub check_ref {
    my ( $git, $ref ) = @_;
    $log->debugf( "$PKG: check_ref(%s)", $ref );

    my ( $old_commit, $new_commit ) = $git->get_affected_ref_range($ref);

    return check_new_or_modified_files( $git, $new_commit, $git->filter_files_in_range( 'AM', $old_commit, $new_commit ) );
}

sub check_patchset {
    my ( $git, undef, $commit ) = @_;
    $log->debugf( "$PKG: check_patchset(%s)", $commit->commit );

    return check_new_or_modified_files( $git, $commit->commit, $git->filter_files_in_commit( $commit->commit ) );
}

# Install hooks
my $options = { config => \&_setup_config };

GITHOOKS_CHECK_PRE_COMMIT( \&check_commit, $options );
GITHOOKS_CHECK_AFFECTED_REFS( \&check_ref, $options );
GITHOOKS_CHECK_PATCHSET( \&check_patchset, $options );

1;

__END__

=for Pod::Coverage check_commit check_new_or_modified_files check_patchset check_ref file_errors

=head1 SYNOPSIS

Use the plugin via the
L<Git::Hooks|Git::Hooks>
interface (git config file).

=for test_synopsis BEGIN { die "SKIP: Git config below."; }

    [githooks]
        plugin = Git::MoreHooks::CheckNonASCII
    [githooks "checknonascii"]
        skip = t/data/*
        skip = qr{\Adoc/unicode-}

=head1 DESCRIPTION

Reports characters outside ASCII in the files a commit adds or modifies, and in
the names of those files. It reports and does nothing else: it never rewrites a
file, never changes a commit, and makes no attempt to transliterate anything.
What to do about a finding is a decision for whoever wrote the line.

=head2 Why this is worth checking

Not tidiness. Text that is not ASCII can carry characters that make a reader see
something other than what is there, and code review is reading.

=over 4

=item *

B<Bidirectional overrides.> C<U+202E> and its relatives reorder the display of
the characters after them. A line can be written so that a reviewer sees a
comment and the compiler sees a statement, or sees a string terminated where it
is not. This is the C<Trojan Source> class of attack, CVE-2021-42574, and it
needs no exotic tooling: it is a text file that renders differently from how it
parses.

=item *

B<Invisible characters.> Zero-width spaces and joiners, C<U+200B> and
C<U+200D>, and soft hyphens, C<U+00AD>, split or join tokens without appearing.
Two identifiers can be different to the compiler and identical on screen.

=item *

B<Homoglyphs.> Cyrillic C<a>, C<U+0430>, is not Latin C<a>, C<U+0061>, and
nothing on screen says so. A URL, a hostname, a variable or a function name can
be replaced by one that cannot be told apart by eye.

=back

What these have in common is that reviewing the file more carefully does not
help, because the file is what is lying. A check that reads bytes does not have
that problem, which is the whole of why this plugin exists.

=head2 What is reported, and what is not

B<Findings are named by codepoint and never printed.> A report saying
C<U+200B> can be looked up; the character itself in a report would be invisible
in the report as well, and a homoglyph would be just as convincing there as in
the source. Each finding gives the file, the line, the byte offset within that
line, and the codepoint:

    lib/Example.pm:42 byte 17: U+202E

A byte that cannot start a valid UTF-8 sequence is reported as the byte it is,
because that is also how a file in some other encoding announces itself:

    lib/Example.pm:7 byte 9: byte 0x80 (not valid UTF-8)

B<Whitespace is not checked.> Tabs, carriage returns, trailing space and the
rest are ASCII, they are a question of layout rather than of misrepresentation,
and L<Git::Hooks::CheckWhitespace|Git::Hooks::CheckWhitespace> already asks it.

B<Commit messages are not checked.> The same reasoning applies to them, but
L<Git::Hooks::CheckLog|Git::Hooks::CheckLog> can already refuse a message by
pattern, so there is nothing here that needs a second implementation.

B<Binary files are skipped>, detected the way git itself detects them: a NUL
byte in the content. A PNG is mostly bytes above C<0x7F> and not one of them is
a homoglyph, so reporting them would be noise that trains people to ignore the
plugin.

=head1 CONFIGURATION

The plugin is configured in the C<githooks.checknonascii> section.

=head2 name PATTERN

May be specified more than once. Only files whose path matches are checked.
B<Unset means every file>, which is the useful default for a rule that applies
to a whole repository.

A pattern is a glob, or C<qr> followed by a delimiter, a regular expression and
the same delimiter again:

    [githooks "checknonascii"]
        name = *.pm
        name = qr{\Alib/.*[.](pm|pl)\z}

=head2 skip PATTERN

May be specified more than once, same grammar as C<name>, and applied after it.
This is how a repository exempts the files where non-ASCII is the subject of the
work rather than a mistake in it -- a test fixture for an encoding conversion, a
document about Unicode, a translation, a quotation in another language:

    [githooks "checknonascii"]
        skip = t/data/encoding/*
        skip = qr{\Adoc/.*-unicode[.]md\z}

C<skip> covers the file name as well as the content, so a file whose B<name> is
deliberately not ASCII is exempted by the same entry.

=head2 max-report N

How many findings to report for one file before summarising the rest. Default
10. A file that is mostly non-ASCII would otherwise produce a page of output
saying nothing the first few lines did not.

=head2 max-size BYTES

A blob larger than this is not read at all. Default 5242880, five mebibytes.

Read with C<get_config_integer>, so git's own suffixes work and C<5M> means
five mebibytes:

=for test_synopsis BEGIN { die "SKIP: Git config below."; }

    [githooks "checknonascii"]
        max-size = 5M

The limit exists so that an enormous object is never slurped into memory: the
size is asked for with C<cat-file -s> before the content is asked for with
C<cat-file -p>, so a huge blob costs one cheap question and nothing else.

B<What it costs is worth stating plainly: a file above the limit is not
checked.> A default this far above any plausible source file is the reason it
is not much of a hole -- a payload hidden in a six megabyte source file is not
hiding -- but it is a hole, and a repository that genuinely commits large text
should raise the limit rather than discover later that those files were never
read. Setting it to 0 disables the check for every file, which is a way of
turning the plugin off and not a way of configuring it.

=head2 Rejecting the file instead of skipping it

L<Git::Hooks::CheckFile|Git::Hooks::CheckFile> has a C<sizelimit> directive
which B<refuses> a file over a given size rather than passing over it, and it
takes the same suffixes:

=for test_synopsis BEGIN { die "SKIP: Git config below."; }

    [githooks "checkfile"]
        sizelimit = 5M

That is the other half of this option, and the two together close the gap
C<max-size> opens. On its own, C<max-size> means a large file is committed
unread. Set C<githooks.checkfile.sizelimit> at or below
C<githooks.checknonascii.max-size> and a file can no longer be both too big to
check and acceptable to commit: whatever this plugin declines to read, that one
declines to accept.

C<CheckFile> also takes C<basename.sizelimit BYTES REGEXP>, for a limit that
applies to some names and not others -- useful where one directory of large
fixtures is expected and the rest of the repository is source.

=head1 LINE ENDINGS

Lines are split on CRLF, CR or LF, so a line number means the same thing
whatever platform the file was written on. Splitting on LF alone reported every
finding in a CR-only file as being on line 1.

The byte offset is counted B<within its line>, from 1, and is a count of bytes
rather than of characters -- so the offset of the character after a three-byte
sequence is three further on, not one. That is deliberate: the offset is there
to be found again in the raw file, and a tool that counts characters disagrees
with one that counts bytes precisely where multi-byte characters are involved,
which is everywhere this plugin reports.

=head1 AFFECTED HOOKS

=over 4

=item * C<pre-commit>

=item * C<update>

=item * C<pre-receive>

=item * C<ref-update>, C<commit-received>, C<submit>, C<patchset-created>,
C<draft-published>

=back

The server side is the one that cannot be avoided. C<git rebase>,
C<git filter-branch> and non-interactive C<git cherry-pick> do not run
C<pre-commit>, and C<--no-verify> switches it off on purpose, so a client-side
check alone is a convenience rather than a guarantee.

=head1 SEE ALSO

L<Git::Hooks::CheckWhitespace|Git::Hooks::CheckWhitespace> for the layout
questions this plugin deliberately leaves alone.

L<Git::Hooks::CheckLog|Git::Hooks::CheckLog> for the same check on commit
messages, via its C<match> option.

L<https://trojansource.codes/> and CVE-2021-42574 for the attack this plugin
reports.
